"use client";

import React, { useState, useEffect, useCallback, useMemo, useRef } from 'react';
import {
    Package, MapPin, LogOut, Settings, Heart, ShoppingBag
} from 'lucide-react';
import { api, API_URL2 } from '@/api/api';
import { CheckoutLogin } from '@/components/LoginComponent';
import { Order } from '@/types';
import { useAuth } from '@/context/AuthContext';
import { SEO } from '@/components/SEO';
import Link from 'next/link';
import { useStore } from '@/context/StoreContext';
import { useRouter } from 'next/navigation';

// Types
type OrderStatus = 'All' | 'Pending' | 'Processing' | 'Shipped' | 'Delivered' | 'Cancelled';
type TabType = 'orders' | 'addresses' | 'wishlist' | 'profile';


// Constants
const ORDER_STATUSES: OrderStatus[] = ['All', 'Pending', 'Processing', 'Shipped', 'Delivered', 'Cancelled'];

const STATUS_STYLES = {
    Delivered: 'bg-green-50 text-green-700',
    Shipped: 'bg-blue-50 text-blue-700',
    Processing: 'bg-yellow-50 text-yellow-700',
    Pending: 'bg-orange-50 text-orange-700',
    Cancelled: 'bg-red-50 text-red-700',
};

const STATUS_DOT_STYLES = {
    Delivered: 'bg-green-500',
    Shipped: 'bg-blue-500',
    Processing: 'bg-yellow-500',
    Pending: 'bg-orange-500',
    Cancelled: 'bg-red-500',
};

export const Account: React.FC = () => {
    const { user, logout } = useAuth();
    const { customerOrders, fetchCustomerOrders } = useStore();
    const router = useRouter();

    // Use ref to track if orders have been loaded
    const ordersLoadedRef = useRef(false);

    // State
    const [activeTab, setActiveTab] = useState<TabType>('orders');
    const [showLogin, setShowLogin] = useState(false);
    const [tokenChecked, setTokenChecked] = useState(false);
    const [ordersLoading, setOrdersLoading] = useState(true);
    const [selectedFilter, setSelectedFilter] = useState<OrderStatus>('All');
    const [profileData, setProfileData] = useState({
        name: '',
        email: '',
    });
    const [profileSaving, setProfileSaving] = useState(false);
    const [error, setError] = useState<string | null>(null);

    // Initialize profile data when user changes
    useEffect(() => {
        if (user) {
            setProfileData({
                name: user.name || '',
                email: user.email || '',
            });
        }
    }, [user]);

    // Check authentication and load orders - FIXED: Run only once on mount
    useEffect(() => {
        // Prevent running multiple times
        if (ordersLoadedRef.current) return;

        const initializeAccount = async () => {
            const token = localStorage.getItem("token");
            if (!token) {
                setShowLogin(true);
                setTokenChecked(true);
                ordersLoadedRef.current = true;
                return;
            }

            try {
                setOrdersLoading(true);
                setError(null);
                await fetchCustomerOrders();
                console.log("✅ Orders loaded successfully");
                setTokenChecked(true);
                ordersLoadedRef.current = true;
            } catch (error: any) {
                console.error("❌ Orders fetch error:", error);

                // Handle 401 - Token expired or invalid
                if (error.response?.status === 401) {
                    console.warn("🚨 Authentication failed - token invalid");
                    setShowLogin(true);
                    setTokenChecked(true);
                    ordersLoadedRef.current = true;
                } else {
                    // Other errors - show message but keep user logged in
                    setError("Failed to load orders. Please try again.");
                }
            } finally {
                setOrdersLoading(false);
            }
        };

        initializeAccount();

        // Empty dependency array - run only once on mount
    }, []); // FIXED: Removed fetchCustomerOrders from dependencies

    // Handle successful login
    const handleLoginSuccess = useCallback(async () => {
        setShowLogin(false);
        setOrdersLoading(true);
        setError(null);

        try {
            await fetchCustomerOrders();
            console.log("✅ Orders loaded after login");
            ordersLoadedRef.current = true;
        } catch (error: any) {
            console.error("❌ Failed to load orders after login:", error);
            setError("Failed to load orders. Please refresh the page.");
        } finally {
            setOrdersLoading(false);
        }
    }, [fetchCustomerOrders]);

    // Handle login modal close
    const handleCloseLogin = useCallback(() => {
        const token = localStorage.getItem('token');
        if (!token) {
            router.back(); // Go back if not logged in
        } else {
            setShowLogin(false);
        }
    }, [router]);

    // Handle logout
    const handleLogout = useCallback(() => {
        localStorage.removeItem('token');
        localStorage.removeItem('user');
        logout();
        ordersLoadedRef.current = false; // Reset the ref on logout
        router.push('/');
    }, [logout, router]);

    // Handle profile save
    const handleSaveProfile = useCallback(async (e: React.FormEvent) => {
        e.preventDefault();

        const token = localStorage.getItem('token');
        if (!token) {
            setError("Please login to update your profile");
            return;
        }

        setProfileSaving(true);
        setError(null);

        try {
            const response = await api.put('/users/profile', {
                name: profileData.name || user?.name,
                email: profileData.email || user?.email,
            }, {
                headers: {
                    Authorization: `Bearer ${token}`,
                },
            });

            // Update local storage with new user data
            const updatedUser = { ...user, ...response.data.user };
            localStorage.setItem('user', JSON.stringify(updatedUser));

            alert('Profile updated successfully!');
        } catch (error: any) {
            console.error('❌ Profile update failed:', error);

            if (error.response?.status === 401) {
                setShowLogin(true);
            } else {
                setError(error.response?.data?.message || 'Failed to update profile');
            }
        } finally {
            setProfileSaving(false);
        }
    }, [profileData, user]);

    // Filter orders
    const filteredOrders = useMemo(() => {
        if (!customerOrders) return [];

        return selectedFilter === 'All'
            ? customerOrders
            : customerOrders.filter((order: Order) => order.status === selectedFilter);
    }, [customerOrders, selectedFilter]);

    // Navigation items
    const navigationItems = useMemo(() => [
        { id: 'orders' as TabType, label: 'My Orders', icon: Package },
        { id: 'addresses' as TabType, label: 'Saved Addresses', icon: MapPin },
        { id: 'wishlist' as TabType, label: 'Wishlist', icon: Heart },
        { id: 'profile' as TabType, label: 'Profile Settings', icon: Settings },
    ], []);

    // Handle navigation click
    const handleNavClick = useCallback((item: typeof navigationItems[0]) => {
        if (item.id === 'wishlist') {
            router.push('/wishlist');
        } else if (item.id === 'addresses') {
            router.push('/addresses');
        } else {
            setActiveTab(item.id);
        }
    }, [router]);

    // Loading state
    if (!tokenChecked) {
        return (
            <div className="min-h-screen flex items-center justify-center bg-gray-50">
                <div className="flex flex-col items-center gap-4">
                    <div className="w-12 h-12 border-4 border-blue-600 border-t-transparent rounded-full animate-spin"></div>
                    <p className="text-gray-600 font-medium">Loading...</p>
                </div>
            </div>
        );
    }

    return (
        <div className="bg-gray-50 min-h-screen py-8 md:py-12">
            {/* Login Modal */}
            {showLogin && (
                <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/50 backdrop-blur-sm">
                    <SEO
                        title="Login to Continue - LAPSHARK"
                        description="Sign in to access your account"
                    />
                    <div className="w-full max-w-md mx-4">
                        <CheckoutLogin
                            onLoginSuccess={handleLoginSuccess}
                            closeLogin={handleCloseLogin}
                        />
                    </div>
                </div>
            )}

            <SEO
                title="My Account - LaptopWorld"
                description="Manage your orders, addresses, and account details."
            />

            <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
                {/* Error Message */}
                {error && (
                    <div className="mb-6 bg-red-50 border border-red-200 text-red-700 px-4 py-3 rounded-lg flex items-center justify-between">
                        <span>{error}</span>
                        <button
                            onClick={() => setError(null)}
                            className="text-red-500 hover:text-red-700"
                        >
                            ×
                        </button>
                    </div>
                )}

                <div className="flex flex-col lg:flex-row gap-8">
                    {/* Sidebar */}
                    <aside className="lg:w-1/4">
                        <div className="bg-white rounded-2xl shadow-sm border border-gray-200 p-6 sticky top-8">
                            {/* User Info */}
                            <div className="flex items-center gap-4 mb-6 pb-6 border-b border-gray-100">
                                <div className="w-16 h-16 rounded-full bg-blue-100 flex items-center justify-center text-blue-600 font-bold text-2xl flex-shrink-0">
                                    {user?.name ? user.name.charAt(0).toUpperCase() : 'U'}
                                </div>
                                <div className="overflow-hidden flex-1">
                                    <h2 className="text-lg font-bold text-gray-900 truncate">
                                        {user?.name || 'User'}
                                    </h2>
                                    <p className="text-sm text-gray-500 truncate">
                                        {user?.mobile || 'User'}
                                    </p>
                                </div>
                            </div>

                            {/* Navigation */}
                            <nav className="space-y-2">
                                {navigationItems.map(item => (
                                    <button
                                        key={item.id}
                                        onClick={() => handleNavClick(item)}
                                        className={`w-full flex items-center px-4 py-3 rounded-xl font-medium transition-colors ${activeTab === item.id
                                            ? 'bg-blue-50 text-blue-600'
                                            : 'text-gray-600 hover:bg-gray-50'
                                            }`}
                                    >
                                        <item.icon className="w-5 h-5 mr-3" />
                                        {item.label}
                                    </button>
                                ))}
                                <button
                                    onClick={handleLogout}
                                    className="w-full flex items-center px-4 py-3 rounded-xl font-medium text-red-500 hover:bg-red-50 transition-colors"
                                >
                                    <LogOut className="w-5 h-5 mr-3" />
                                    Sign Out
                                </button>
                            </nav>
                        </div>
                    </aside>

                    {/* Main Content */}
                    <main className="lg:w-3/4">
                        {/* Orders Tab */}
                        {activeTab === 'orders' && (
                            <div className="bg-white rounded-2xl shadow-sm border border-gray-200 overflow-hidden">
                                {/* Header with Filters */}
                                <div className="p-6 border-b border-gray-100">
                                    <h2 className="text-2xl font-bold text-gray-900 mb-4">My Orders</h2>

                                    {/* Filter Tabs */}
                                    <div className="flex items-center justify-between gap-4">
                                        <div className="flex items-center gap-2 overflow-x-auto scrollbar-hide pb-2">
                                            {ORDER_STATUSES.map((status) => (
                                                <button
                                                    key={status}
                                                    onClick={() => setSelectedFilter(status)}
                                                    className={`px-4 py-2 rounded-full text-sm font-medium whitespace-nowrap transition-all ${selectedFilter === status
                                                        ? 'bg-slate-900 text-white shadow-md'
                                                        : 'bg-gray-100 text-gray-700 hover:bg-gray-200'
                                                        }`}
                                                >
                                                    {status}
                                                </button>
                                            ))}
                                        </div>
                                    </div>
                                </div>

                                {/* Orders List */}
                                {ordersLoading ? (
                                    <div className="p-12 text-center">
                                        <div className="w-12 h-12 border-4 border-blue-600 border-t-transparent rounded-full animate-spin mx-auto mb-4"></div>
                                        <p className="text-gray-600 font-medium">Loading your orders...</p>
                                    </div>
                                ) : !filteredOrders || filteredOrders.length === 0 ? (
                                    <div className="p-12 text-center text-gray-500">
                                        <div className="w-20 h-20 bg-gray-100 rounded-full flex items-center justify-center mx-auto mb-4">
                                            <ShoppingBag className="w-10 h-10 text-gray-400" />
                                        </div>
                                        <h3 className="text-lg font-bold text-gray-900 mb-2">
                                            {selectedFilter === 'All' ? 'No orders yet' : `No ${selectedFilter.toLowerCase()} orders`}
                                        </h3>
                                        <p className="text-gray-500 mb-6">
                                            {selectedFilter === 'All'
                                                ? 'Start shopping and your orders will appear here'
                                                : `You don't have any ${selectedFilter.toLowerCase()} orders`}
                                        </p>
                                        {selectedFilter === 'All' && (
                                            <Link
                                                href="/products"
                                                className="inline-flex items-center gap-2 bg-slate-900 text-white px-8 py-3 rounded-lg font-bold hover:bg-slate-800 transition-all"
                                            >
                                                <ShoppingBag className="w-4 h-4" />
                                                Start Shopping
                                            </Link>
                                        )}
                                    </div>
                                ) : (
                                    <div className="divide-y divide-gray-100">
                                        {filteredOrders.map((order: Order) => (
                                            <OrderCard
                                                key={order.id}
                                                order={order}
                                                onClick={() => router.push(`/products/${order.items[0].productId}`)}
                                            />
                                        ))}
                                    </div>
                                )}
                            </div>
                        )}

                        {/* Profile Tab */}
                        {activeTab === 'profile' && (
                            <div className="bg-white rounded-2xl shadow-sm border border-gray-200 p-6 md:p-8">
                                <h2 className="text-xl font-bold text-gray-900 mb-6">Profile Settings</h2>
                                <form className="space-y-6 max-w-lg" onSubmit={handleSaveProfile}>
                                    <div>
                                        <label className="block text-sm font-bold text-gray-700 mb-2">
                                            Full Name
                                        </label>
                                        <input
                                            type="text"
                                            className="w-full p-3 border border-gray-300 rounded-xl focus:ring-2 focus:ring-blue-500 outline-none"
                                            value={profileData.name}
                                            onChange={(e) => setProfileData(prev => ({ ...prev, name: e.target.value }))}
                                        />
                                    </div>
                                    <div>
                                        <label className="block text-sm font-bold text-gray-700 mb-2">
                                            Mobile Number
                                        </label>
                                        <input
                                            type="tel"
                                            className="w-full p-3 border border-gray-300 rounded-xl bg-gray-50"
                                            value={user?.mobile || ''}
                                            disabled
                                        />
                                        <p className="text-sm text-gray-500 mt-1">
                                            Mobile number cannot be changed
                                        </p>
                                    </div>
                                    <div>
                                        <label className="block text-sm font-bold text-gray-700 mb-2">
                                            Email Address (Optional)
                                        </label>
                                        <input
                                            type="email"
                                            className="w-full p-3 border border-gray-300 rounded-xl focus:ring-2 focus:ring-blue-500 outline-none"
                                            value={profileData.email}
                                            onChange={(e) => setProfileData(prev => ({ ...prev, email: e.target.value }))}
                                        />
                                    </div>
                                    <button
                                        type="submit"
                                        disabled={profileSaving}
                                        className="bg-blue-600 text-white px-6 py-3 rounded-xl font-bold hover:bg-blue-700 transition-colors shadow-lg disabled:opacity-50 disabled:cursor-not-allowed flex items-center gap-2"
                                    >
                                        {profileSaving ? (
                                            <>
                                                <div className="w-4 h-4 border-2 border-white border-t-transparent rounded-full animate-spin"></div>
                                                Saving...
                                            </>
                                        ) : (
                                            'Save Changes'
                                        )}
                                    </button>
                                </form>
                            </div>
                        )}
                    </main>
                </div>
            </div>
        </div>
    );
};

// Separate OrderCard component for better performance
const OrderCard: React.FC<{ order: Order; onClick: () => void }> = React.memo(({ order, onClick }) => {
    return (
        <div
            className="p-6 hover:bg-gray-50 transition-colors cursor-pointer group"
            onClick={onClick}
        >
            {/* Status and Date */}
            <div className="flex items-center gap-3 mb-4 flex-wrap">
                <span className={`inline-flex items-center gap-1.5 px-3 py-1 rounded-full text-xs font-semibold ${STATUS_STYLES[order.status as keyof typeof STATUS_STYLES] || 'bg-gray-50 text-gray-700'
                    }`}>
                    <span className={`w-2 h-2 rounded-full ${STATUS_DOT_STYLES[order.status as keyof typeof STATUS_DOT_STYLES] || 'bg-gray-500'
                        }`}></span>
                    {order.status}
                </span>
                <span className="text-sm text-gray-500">
                    {new Date(order.date).toLocaleDateString("en-IN", {
                        day: "numeric",
                        month: "short",
                        year: "numeric"
                    })}
                </span>
            </div>

            {/* Order Content */}
            <div className="flex items-center gap-4">
                {/* Product Images */}
                <div className="flex-shrink-0">
                    {order.items.length === 1 ? (
                        <div className="w-20 h-20 bg-gray-50 rounded-lg border border-gray-200 p-2">
                            <img
                                src={API_URL2 + order.items[0].image}
                                alt={order.items[0].title}
                                className="w-full h-full object-contain"
                                loading="lazy"
                            />
                        </div>
                    ) : (
                        <div className="relative w-20 h-20">
                            <div className="w-20 h-20 bg-gray-50 rounded-lg border border-gray-200 p-2">
                                <img
                                    src={API_URL2 + order.items[0].image}
                                    alt={order.items[0].title}
                                    className="w-full h-full object-contain"
                                    loading="lazy"
                                />
                            </div>
                            <div className="absolute -bottom-1 -right-1 w-7 h-7 bg-slate-900 text-white rounded-full flex items-center justify-center text-xs font-bold shadow-lg">
                                +{order.items.length - 1}
                            </div>
                        </div>
                    )}
                </div>

                {/* Order Details */}
                <div className="flex-1 min-w-0">
                    <h3 className="text-sm font-bold text-gray-600 mb-1 uppercase">
                        #{order.orderId}
                    </h3>
                    <p className="text-sm text-gray-600 line-clamp-2 mb-2">
                        {order.items.length === 1
                            ? order.items[0].title
                            : `${order.items[0].title} ${order.items.length > 1 ? `& ${order.items.length - 1} more item${order.items.length > 2 ? 's' : ''}` : ''}`
                        }
                    </p>
                    <p className="text-base font-bold text-gray-900">
                        ₹{order.total.toLocaleString('en-IN')}
                    </p>
                </div>

                {/* Arrow Icon */}
                <div className="flex-shrink-0">
                    <svg
                        className="w-6 h-6 text-gray-400 group-hover:text-gray-600 transition-colors"
                        fill="none"
                        stroke="currentColor"
                        viewBox="0 0 24 24"
                    >
                        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 5l7 7-7 7" />
                    </svg>
                </div>
            </div>
        </div>
    );
});

OrderCard.displayName = 'OrderCard';